// Получаем транскрипт от ASR
const transcript = $input.first().json.text;

// Промпт: ТОЛЬКО time_violation
const prompt = `Проанализируй текст звонка коллектора. Найди ТОЛЬКО нарушение по времени.

Нарушение времени = звонок вне разрешённого времени (до 8:00 или после 22:00 в рабочие дни; до 9:00 или после 20:00 в выходные).

Признаки: прямое упоминание времени в тексте ("сейчас 22:15", "половина одиннадцатого", "вечер", "ночь").

Верни СТРОГО JSON без пояснений:
{
  "type": "time_violation",
  "found": true или false,
  "quote": "точная цитата из текста, подтверждающая нарушение (или пустая строка)",
  "confidence": число от 0.0 до 1.0,
  "reasoning": "краткое объяснение"
}

ТЕКСТ ЗВОНКА:
${transcript}`;

return {
  json: {
    model: "qwen2.5:7b",
    prompt: prompt,
    stream: false,
    options: {
      temperature: 0.0,
      top_p: 0.9
    }
  }
};

