// Получаем транскрипт от ASR
const transcript = $input.first().json.text;

// Промпт: ТОЛЬКО lack_of_identification
const prompt = `Проанализируй текст звонка коллектора. Найди ТОЛЬКО нарушение по идентификации оператора.

Нарушение = оператор не представился в начале разговора.

Признаки:
- В начале разговора оператор НЕ назвал:
  - своё ФИО или имя
  - название организации (МФО, банк, коллекторское агентство)
  - должность

- Оператор отказался представляться ("я не обязан представляться", "это неважно").

НЕ является нарушением:
- Оператор представился только по имени ("это Анна из банка") — этого достаточно.
- Оператор назвал организацию, но не назвал ФИО — это НЕ нарушение, если организация названа.

Верни СТРОГО JSON без пояснений:
{
  "type": "lack_of_identification",
  "found": true или false,
  "quote": "точная цитата из текста (или пустая строка)",
  "confidence": число от 0.0 до 1.0,
  "reasoning": "краткое объяснение"
}

ТЕКСТ ЗВОНКА:
${transcript}`;

return {
  json: {
    model: "qwen2.5:7b",
    prompt: prompt,
    stream: false,
    options: {
      temperature: 0.0,
      top_p: 0.9
    }
  }
};

const joinOutput = $input.first().json;

const violations = [];
const checked = [];

// Проходим по всем ключам верхнего уровня
for (const key of Object.keys(joinOutput)) {
  const input = joinOutput[key];

  // Проверяем, что это объект с полем response
  if (!input || typeof input !== 'object') continue;

  // response может быть в input.response или в input напрямую
  let response = input.response || input;

  // Если response — строка, парсим JSON
  let parsed;
  try {
    parsed = typeof response === 'string' 
      ? JSON.parse(response) 
      : response;
  } catch (e) {
    const match = String(response).match(/\{[\s\S]*\}/);
    if (!match) continue;
    try { parsed = JSON.parse(match[0]); } catch (e2) { continue; }
  }

  if (parsed && parsed.type) {
    checked.push(parsed.type);
    if (parsed.found === true) {
      violations.push({
        type: parsed.type,
        quote: parsed.quote,
        confidence: parsed.confidence,
        reasoning: parsed.reasoning
      });
    }
  }
}

return {
  json: {
    violations: violations,
    total_checked: checked.length,
    total_found: violations.length,
    checked_types: checked
  }
};
